// ------------------------------------------------------------ battle keys
function battleKey(e) {
  if (!B) return;
  const k = e.key;
  if (k === 'Escape') {
    e.preventDefault(); setPause(true); return;   // normally caught earlier by the capture listener
  }
  if (B.paused || B.over) return;
  if (k === 'Delete') { e.preventDefault(); if (!B.cw) clearWord(); return; }
  if (B.cw) {
    if (k === 'Tab') { e.preventDefault(); cwNext(e.shiftKey ? -1 : 1); return; }
    if (k === 'Enter') { e.preventDefault(); cwNext(); return; }
    if (k === 'Backspace') { e.preventDefault(); cwBackspace(); return; }
    if (k === '?') { e.preventDefault(); cwReveal(); return; }
    if (k.startsWith('Arrow')) { e.preventDefault(); cwArrow(k === 'ArrowUp' ? -1 : k === 'ArrowDown' ? 1 : 0, k === 'ArrowLeft' ? -1 : k === 'ArrowRight' ? 1 : 0); return; }
    const ch = letterKey(e); if (ch) { e.preventDefault(); cwType(ch); }
    return;
  }
  if (k === 'Enter') { e.preventDefault(); submitWord(); return; }
  if (k === 'Backspace') { e.preventDefault(); meshBackspace(); return; }
  if (k === ' ') { e.preventDefault(); if (B.meter >= METER_MAX) openFinisher(); else fb(`Zagovor še ni poln (${Math.floor(B.meter)}/${METER_MAX}).`, 'warn'); return; }
  if (k === 'ArrowLeft') { e.preventDefault(); cycleTarget(-1); return; }
  if (k === 'ArrowRight') { e.preventDefault(); cycleTarget(1); return; }
  if (k === '1') { useHint(); return; }
  if (k === '2') { shuffleGrid(true); return; }
  if (k === '3') { openBag(); return; }
  const ch = letterKey(e); if (ch) { e.preventDefault(); meshType(ch); }
}
function letterKey(e) {
  if (e.ctrlKey || e.metaKey || e.altKey || e.key.length !== 1) return null;
  const ch = e.key.toLowerCase();
  return /^[abcčdefghijklmnoprsštuvzž]$/.test(ch) ? ch : null;
}

// ============================================================ chest event (timed)
// Any real word built from the letters earns a partial reward (longer word, bigger reward).
// The hidden word opens the chest and earns the big reward.
const CHEST_XP_WIN = 50;
function startChest(node) {
  const item = pick(CHESTS);
  let letters = shuffle([...item.w]);
  while (letters.join('') === item.w) letters = shuffle(letters);
  const t = (S.mode === 'real' ? 40 : 80) * (has('pisanica') ? 1.5 : 1);
  S.ev = { node, kind: 'chest', item, letters: letters.map(ch => ({ ch, used: false })), sel: [], time: t, timeMax: t,
    done: false, found: [], msg: '', msgKind: '' };
  renderChest();
  showTut('chest');
}
function renderChest() {
  const E = S.ev; SCR.innerHTML = '';
  const guess = E.sel.map(i => E.letters[i].ch).join('');
  SCR.append(h('div', { class: 'event' },
    h('div', { class: 'bhead' }, h('div', { class: 't' }, 'Zaklenjena skrinja', h('small', {}, 'dogodek na čas'))),
    h('div', { class: 'panel' },
      h('div', { class: 'chestbox' }, objEl('skrinja', E.done && E.win ? 1 : 0, 'big'),
        h('div', {}, h('div', {}, 'Iz črk sestavi besedo in jo pošlji. Imaš en poskus: beseda iz vseh črk odpre skrinjo, krajša prava beseda jo le priškrne in prinese del nagrade (daljša beseda, večji del).'),
          h('div', { style: { color: 'var(--gold)', 'margin-top': '6px' } }, 'Namig za skrito besedo: ', E.item.clue))),
      h('div', { class: 'timer', style: { margin: '14px 0 4px' } }, h('i', { ref: el => UI.evTimer = el, style: { width: clamp(100 * E.time / E.timeMax, 0, 100) + '%' } })),
      h('div', { class: 'sendrow' },
        h('div', { class: 'guess' }, [...E.item.w].map((_, k) => h('span', { class: 'lt' }, E.sel[k] != null ? E.letters[E.sel[k]].ch : ''))),
        E.done ? null : h('button', { class: 'btn primary send' + (guess.length >= MINW() ? ' ready' : ''), disabled: guess.length < MINW(), onclick: chestSubmit }, 'Pošlji ', h('kbd', {}, 'Enter'))),
      h('div', { class: 'letters' }, E.letters.map((l, i) => h('div', { class: 'tile' + (l.used ? ' used' : ''), onclick: () => chestPick(i) }, l.ch))),
      E.msg ? h('p', { class: 'fb ' + E.msgKind }, E.msg) : null,
      E.loot ? h('p', { class: 'lootline' }, itemIcon(E.loot.id), h('b', {}, E.loot.name), ' — ', E.loot.text) : null,
      E.done ? h('div', {}, h('button', { class: 'btn primary', onclick: () => finishEvent() }, 'Na pot ', h('kbd', {}, 'Enter')))
      : h('div', { class: 'row', style: { 'justify-content': 'flex-start', 'flex-wrap': 'wrap' } },
        h('button', { class: 'btn small', onclick: chestBack }, '⌫ Briši'),
        h('button', { class: 'btn small', onclick: chestClear }, 'Počisti ', h('kbd', {}, 'Del')),
        h('button', { class: 'btn small', onclick: () => { E.letters = shuffle(E.letters.map((l, i) => ({ ...l, i }))); chestRemap(); } }, 'Premešaj')),
      null)));
}
function chestRemap() {
  const E = S.ev;
  // after shuffling, selection indices must follow their letters
  const map = new Map(E.letters.map((l, ni) => [l.i, ni]));
  E.sel = E.sel.map(oi => map.get(oi)); E.letters.forEach(l => delete l.i);
  renderChest();
}
function chestPick(i) {
  sfx('sel', { vol: .7 });
  const E = S.ev; if (E.done) return;
  const l = E.letters[i];
  if (l.used) { const at = E.sel.indexOf(i); E.sel.splice(at); E.letters.forEach((x, k) => x.used = E.sel.includes(k)); renderChest(); return; }
  l.used = true; E.sel.push(i);
  renderChest();
}
function chestType(ch) {
  const E = S.ev; if (E.done) return;
  const i = E.letters.findIndex(l => !l.used && letterEq(l.ch, ch));
  if (i >= 0) chestPick(i);
}
function chestBack() { const E = S.ev; if (E.done || !E.sel.length) return; const i = E.sel.pop(); E.letters[i].used = false; renderChest(); }
